// Expand the annual values onto the shared monthly IVI_MONTHS axis: each month
// takes its calendar year's value (forward-filled across year gaps); months after
// the last year carry the last value; months before the first year are zero.
function expand(annual: Record<string, number[]>): Record<string, number[]> {
  const out: Record<string, number[]> = {};
  for (const [city, vals] of Object.entries(annual)) {
    // year → value, forward-filled so a missing middle year inherits the previous.
    const byYear = new Map<number, number>();
    let last = 0;
    for (let i = 0; i < EU_YEARS.length; i++) {
      if (vals[i] > 0) last = vals[i];
      byYear.set(EU_YEARS[i], last);
    }
    const firstYear = EU_YEARS[0];
    const lastYear = EU_YEARS[EU_YEARS.length - 1];
    const lastVal = byYear.get(lastYear) || 0;
    out[city] = IVI_MONTHS.map((ym) => {
      const y = Number(ym.slice(0, 4));
      if (y < firstYear) return 0;
      if (y > lastYear) return lastVal;
      return byYear.get(y) || 0;
    });
  }
  return out;
}

// Skill → country id → monthly vacancy history (aligned to IVI_MONTHS).
export const EU_SERIES: Record<string, Record<string, number[]>> =
  Object.fromEntries(Object.entries(EU_ANNUAL).map(([s, a]) => [s, expand(a)]));

// Skill → latest-year country vacancy count (current heat map).
export const EU_SKILL_BY_CITY: Record<string, Record<string, number>> =
  Object.fromEntries(
    Object.entries(EU_SERIES).map(([s, byCity]) => [
      s,
      Object.fromEntries(Object.entries(byCity).map(([c, arr]) => [c, arr[arr.length - 1]])),
    ]),
  );
